import ModuleWorkspace from './ModuleWorkspace.vue';
import {ref,onMounted,nextTick,watch,computed} from 'vue';import type {ECharts} from 'echarts/core';
const currentDataGroup=computed(()=>dataMenuGroups.find(group=>group.items.includes(subsection.value)));
const inventorySections=['电源台账','储能台账','负荷与保供目标','变压器与开关','二次设备与通信','经济参数'];
const networkDefaults={wind_node:18,pv_node:30,voltage_min_pu:.95,voltage_max_pu:1.05,linear_voltage_guard_pu:.955};
const customNetwork=ref<any>(null);const sourceImport=ref<any>(null);const sourceImportCsv=ref('');const defaultNetwork=ref<any>(null);
const currentLines=computed(()=>customNetwork.value?.lines||defaultNetwork.value?.lines||[]);
const faultSelection=computed<number[]>({get:()=>failedLines.value.trim()?failedLines.value.split(/[,，]/).map(Number):[],set:v=>{failedLines.value=v.join(',')}});
fetch('/api/network/case33').then(r=>{if(r.ok)return r.json();throw Error('网络读取失败')}).then(v=>defaultNetwork.value=v).catch(()=>{});
const networkParameters=ref({...networkDefaults});
const chartMode=ref('供需平衡');
const productionId=ref<string|null>(null);const productionCsv=ref('');const activeProductionId=computed(()=>csv.value===productionCsv.value?productionId.value:null);
const project=ref<any>(null);const projects=ref<any[]>([]);const scenarioId=ref<string|null>(null);const projectMessage=ref('');
const stages=ref<Stage[]>([]);const stageSnapshot=ref('[]');const model=ref('aggregate');const failedLines=ref('');const branchLimit=ref(5000);
const menus=['工程工作台','数据管理','保供场景生成','承灾极限分析','电力电量平衡','保供能力提升','源储协同配置','离网稳定判别','黑启动路径优化','方案与报告','系统与接口'];const active=ref('工程工作台');const csv=ref('');const busy=ref(true);const error=ref('');const result=ref<any>(null);const history=ref<any[]>([]);const chart=ref<HTMLElement>();let plot:ECharts|undefined;let chartRequest=0;
const operatingCondition=ref('极端保供');
const scenarioSettingsOpen=ref(0);
const selectedScenario=ref<any>(null);
const dataWorkspace=ref<InstanceType<typeof DataWorkspace>>();
const desktopMenu=ref('');
const workspacePanel=ref('');const presentation=ref(false);
watch(subsection,()=>{workspacePanel.value='';if(subsection.value!=='故障与恢复场景')scenarioSettingsOpen.value=0});
const resultDetail=ref('分阶段指标');
const sidebarCompact=ref(false);
const balanceMode=ref('汇总／网络平衡');
const balanceView=computed(()=>subsection.value==='计算任务'?'计算任务':['平衡结果','网络逐时结果'].includes(subsection.value)?'分析结果':'分析设置');
const currentNavigation=computed(()=>workflowNavigation.flatMap(group=>group.items.map(item=>({group:group.label,...item}))).find(item=>item.menu===active.value&&item.sections.includes(subsection.value))||workflowNavigation.flatMap(group=>group.items.map(item=>({group:group.label,...item}))).find(item=>item.menu===active.value));
const currentGroup=computed(()=>workflowNavigation.find(group=>group.label===currentNavigation.value?.group));
/** Context toolbar is deliberately small: each document exposes only actions that
 * belong to the current task. Opening an editor never submits a calculation. */
const contextTools=computed(()=>{
 const menu=active.value, section=subsection.value;
 if(menu==='数据管理') return section==='源荷时序'||section==='阿拉山口资料'
  ? ['导入数据','数据编辑','校验','保存'] : section==='电网拓扑'
  ? ['导入拓扑','属性','校验','保存'] : ['数据编辑','属性','校验','保存'];
 if(menu==='保供场景生成') return section==='生产序列嵌入'
  ? ['场景模板','故障场景','保存工程'] : ['场景模板','故障场景','保存工程'];
 if(menu==='电力电量平衡') return section==='计算任务'
  ? ['分析设置','任务中心'] : section==='平衡结果'||section==='网络逐时结果'
  ? ['指标','逐时明细','计算档案'] : ['选择场景','模型与资源','运行阶段','参数设置','输入校验'];
 if(menu==='保供能力提升') return ['策略库','资源调整','效果对比'];
 if(menu==='源储协同配置') return [];
 if(menu==='方案与报告') return ['打开档案','方案对比','质效评价'];
 if(menu==='承灾极限分析'||menu==='离网稳定判别'||menu==='黑启动路径优化') return ['分析设置','任务详情','查看结果'];
 return ['任务中心','保存工程'];
});
function runContextTool(tool:string){
 const sectionAliases:Record<string,string>={
  '策略库':'策略库','资源调整':'资源调整','效果对比':'效果对比',
  '候选资源':'候选资源','目标与约束':'目标与约束','规划阶段':'规划阶段','配置方式':'配置结果','配置结果':'配置结果',
  '打开档案':'计算档案','方案对比':'方案对比','质效评价':'质效评价',
  '分析设置':'分析设置'
 };
 if(sectionAliases[tool]&&['保供能力提升','源储协同配置','方案与报告'].includes(active.value)){navigateSection(active.value,sectionAliases[tool]);return}
 if(tool==='分析设置'&&['承灾极限分析','离网稳定判别','黑启动路径优化'].includes(active.value)){navigateSection(active.value,active.value==='离网稳定判别'?'判别对象':active.value==='黑启动路径优化'?'恢复分区':'分析设置');return}
 if(tool==='任务详情'&&['承灾极限分析','离网稳定判别','黑启动路径优化'].includes(active.value)){navigateSection('系统与接口','计算任务');return}
 if(tool==='参数设置'||tool==='设置'||tool==='模型与资源') {if(active.value==='保供场景生成'){scenarioSettingsOpen.value++;return}workspacePanel.value='参数';return}
 if(tool==='计算档案'){navigateSection('方案与报告','计算档案');return}
 if(tool==='分析设置'&&active.value==='电力电量平衡'){navigateSection(active.value,'模型与资源');return}
 if(tool==='指标') {workspacePanel.value='指标';return}
 if(tool==='逐时明细'||tool==='明细'||tool==='任务详情') {workspacePanel.value='明细';return}
 if(tool==='运行阶段') {workspacePanel.value='参数';return}
 if(tool==='提交计算') {if(active.value==='电力电量平衡'&&balanceMode.value==='汇总／网络平衡')run().catch(e=>error.value=String(e));return}
 if(tool==='查看结果'||tool==='结果类型') {
  if(active.value==='电力电量平衡')navigateSection('电力电量平衡','平衡结果');
  else if(active.value==='承灾极限分析')navigateSection(active.value,'承灾边界');
  else if(active.value==='离网稳定判别')navigateSection(active.value,'风险结果');
  else if(active.value==='黑启动路径优化')navigateSection(active.value,'恢复序列');
  return
 }
 if(tool==='导出'||tool==='导出报告') {desktopMenu.value='导出';return}
 if(tool==='故障场景'){navigateSection('保供场景生成','故障与恢复场景');return}
 if(tool==='任务中心') {navigateSection('系统与接口','计算任务');return}
 if(tool==='数据编辑'||tool==='属性') {if(tool==='属性')dataWorkspace.value?.openProperties();else dataWorkspace.value?.openEditor();return}
 if(tool==='校验'||tool==='输入校验') {navigateSection('数据管理','数据版本管理');return}
 if(tool==='保存工程'||tool==='保存') {saveProject().catch(e=>error.value=String(e));return}
 if(tool==='应用场景') {navigateSection('保供场景生成','故障与恢复场景');projectMessage.value='请在场景工作区选择已生成场景后应用';return}
 if(tool==='生成场景'||tool==='生成当前视图') {scenarioSettingsOpen.value++;projectMessage.value='已打开场景参数，请核对后提交生成';return}
 if(tool==='导入数据') {navigateSection('数据管理','源荷时序').then(()=>dataWorkspace.value?.openEditor());return}
 if(tool==='导入拓扑') {navigateSection('数据管理','电网拓扑').then(()=>dataWorkspace.value?.openEditor());return}
 if(tool==='选择场景'||tool==='场景模板'||tool==='工况选择') {navigateSection('保供场景生成','典型场景库');return}
 if(tool==='复算'||tool==='优化运行') {projectMessage.value='当前动作需要已选择基准和可用后端任务';return}
}
const inputIssue=computed(()=>{const check=inspectTimeSeries(csv.value);if(check.totalIssues)return `源荷格式有${check.totalIssues}项问题`;if(model.value==='case33'&&check.count>168)return '网络平衡最多168小时，请缩短时序或更换模式';let previous=0;const names=new Set<string>();for(const stage of stages.value){if(!stage.name.trim()||names.has(stage.name.trim())||!Number.isInteger(stage.end_hour)||stage.end_hour<=previous)return '运行阶段名称或结束小时不合法';names.add(stage.name.trim());previous=stage.end_hour}return stages.value.length&&previous!==check.count?'运行阶段未覆盖完整输入时序':''});
async function continueWorkflow(){const group=currentGroup.value;if(!group)return;const item=currentNavigation.value;const index=group.items.findIndex(v=>v.label===item?.label);await saveProject();if(index<group.items.length-1)await openWorkflow(group,group.items[index+1]);else{const i=workflowNavigation.indexOf(group);if(i<5)await openWorkflow(workflowNavigation[i+1]);}}
const expandedGroup=ref('工程工作台');
watch(currentGroup,value=>{if(value)expandedGroup.value=value.label});
async function openWorkflow(group:typeof workflowNavigation[number],item=group.items[0]){expandedGroup.value=group.label;await navigateSection(item.menu,item.sections[0]);}
watch(active,()=>{subsection.value=children[active.value]?.[0]||''},{flush:'sync'});
function normalizeStages(value:Stage[]|undefined){return (value||[]).map(stage=>({...stage,grid_ratio:stage.grid_ratio??1,emergency_ratio:stage.emergency_ratio??1,failed_lines:stage.failed_lines??[]}))}
function sameParameters(a:Record<string,number>,b:Record<string,number>){return Object.keys(a).length===Object.keys(b).length&&Object.entries(a).every(([key,value])=>value===b[key])}
const params=ref({storage_power_kw:500,storage_energy_kwh:2000,emergency_gen_kw:300,grid_channel_kw:0,soc_initial_ratio:.8,soc_min_ratio:.1,soc_max_ratio:.95,eta_charge:.92,eta_discharge:.9,critical_load_ratio:.2,important_load_ratio:.35});const labels:Record<string,string>={storage_power_kw:'储能功率 / kW',storage_energy_kwh:'储能容量 / kWh',emergency_gen_kw:'应急电源 / kW',grid_channel_kw:'外部供电上限 / kW',soc_initial_ratio:'初始SOC / 比例',soc_min_ratio:'SOC下限 / 比例',soc_max_ratio:'SOC上限 / 比例',eta_charge:'充电效率 / 比例',eta_discharge:'放电效率 / 比例',critical_load_ratio:'关键负荷占比',important_load_ratio:'重要负荷占比'};
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){const id=project.value?.id;const records=await api('/api/runs'+(id?'?project_id='+id:''));if(project.value?.id===id)history.value=records}
function state(){return {network:customNetwork.value,sourceImport:sourceImportCsv.value===csv.value?sourceImport.value:null,csv:csv.value,parameters:params.value,stages:stages.value,networkParameters:networkParameters.value,model:model.value,failedLines:failedLines.value,branchLimit:branchLimit.value,scenarioId:scenarioId.value,productionSequenceId:activeProductionId.value}}
async function saveProject(){if(!project.value)return;const wasBusy=busy.value;busy.value=true;try{project.value=await api('/api/projects/'+project.value.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...project.value,state:state(),expected_revision:project.value.revision})});projectMessage.value='工程已保存 · 版本 '+project.value.revision;projects.value=await api('/api/projects')}finally{busy.value=wasBusy}}
async function createProject(){busy.value=true;try{if(project.value)await saveProject();const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'新建保供工程',state:{csv:'timestamp,load_kw,wind_kw,pv_kw\n'}})});await openProject(p.id,false)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function openProject(id:string,save=true){busy.value=true;try{if(save&&project.value)await saveProject();const p=await api('/api/projects/'+id);project.value=p;selectedScenario.value=null;eventCsv.value='';const v=p.state;customNetwork.value=v.network||null;sourceImport.value=v.sourceImport||null;csv.value=v.csv||'';sourceImportCsv.value=csv.value;productionId.value=v.productionSequenceId||null;productionCsv.value=csv.value;params.value={storage_power_kw:500,storage_energy_kwh:2000,emergency_gen_kw:300,grid_channel_kw:0,soc_initial_ratio:.8,soc_min_ratio:.1,soc_max_ratio:.95,eta_charge:.92,eta_discharge:.9,critical_load_ratio:.2,important_load_ratio:.35,...v.parameters};networkParameters.value={...networkDefaults,...v.networkParameters};stages.value=normalizeStages(v.stages);model.value=v.model||'aggregate';failedLines.value=v.failedLines||'';branchLimit.value=v.branchLimit||5000;scenarioId.value=v.scenarioId||null;result.value=null;projects.value=await api('/api/projects');await refresh();localStorage.setItem('terminal-power.last-project',p.id);projectMessage.value='当前工程：'+p.name+' · 版本 '+p.revision}catch(e){error.value=String(e)}finally{busy.value=false}}
function applyProjected(value:string){productionId.value=null;csv.value=value;scenarioId.value=null;result.value=null;projectMessage.value='已更新源荷序列，请保存工程';}
function applyProduction(value:string,id:string,embeddedScenarioId?:string){applyProjected(value);productionId.value=id;productionCsv.value=value;scenarioId.value=embeddedScenarioId||null}
function applyScenario(id:string){scenarioId.value=id;active.value='电力电量平衡';projectMessage.value='故障场景已选择，计算时将校验时间轴'}
function loadAnnualExample(){applyProjected(annualDisplayExample());sourceImport.value=null;stages.value=[];projectMessage.value='已载入8760小时合成展示例，非阿拉山口实测或预测数据；未保存工程、未运行计算。';}
async function demo(){try{csv.value=(await api('/api/demo')).csv;result.value=null;error.value=''}catch(e){error.value=String(e)}}
async function run(){if(busy.value)return;if(inputIssue.value){error.value=inputIssue.value;await navigateSection('电力电量平衡','模型与资源');workspacePanel.value='参数';return}busy.value=true;error.value='';const submittedProject=project.value?.id;try{await saveProject();const calculated=await api('/api/balance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({network:customNetwork.value,source_import:sourceImportCsv.value===csv.value?sourceImport.value:null,project_id:project.value?.id,project_revision:project.value?.revision,scenario_id:scenarioId.value,production_sequence_id:activeProductionId.value,stages:stages.value,network_parameters:networkParameters.value,csv:csv.value,parameters:params.value,model:model.value,failed_lines:failedLines.value.trim()?failedLines.value.split(/[,，]/).map(Number):[],branch_limit_kw:branchLimit.value})});if(project.value?.id!==submittedProject)return;result.value=calculated;stageSnapshot.value=JSON.stringify(stages.value);await refresh();if(active.value==='电力电量平衡'&&subsection.value==='计算任务')subsection.value='平衡结果';projectMessage.value='计算完成并已归档 · '+calculated.id;await draw()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function draw(){
 const request=++chartRequest;await nextTick();
 if(!chart.value||!result.value||balanceView.value!=='分析结果'||balanceMode.value!=='汇总／网络平衡'){plot?.dispose();plot=undefined;return}
 const runtime=await import('./chartRuntime');
 if(request!==chartRequest||!chart.value||!result.value)return;
 plot?.dispose();plot=runtime.init(chart.value);const rows=result.value.rows;
 if(chartMode.value==='网络电压'&&result.value.model!=='case33'){chartMode.value='供需平衡';return}
 const soc=chartMode.value==='储能SOC';const voltage=chartMode.value==='网络电压';
 const fields=voltage?[['交流最低电压','ac_min_voltage_pu'],['交流最高电压','ac_max_voltage_pu']]:soc?[['SOC','soc']]:chartMode.value==='资源出力'?[['外部供电','firm_grid_dispatch_kw'],['应急发电','emergency_gen_kw'],['储能放电','storage_discharge_kw'],['储能充电（负值）','storage_charge_kw']]:[['负荷','load_kw'],['风光可用','available_re_kw'],['实际供电','load_served_kw'],['缺供功率','power_deficit_kw']];
 const series:any[]=fields.map(([name,key])=>({name,type:'line',showSymbol:false,data:rows.map((r:any)=>r[key]==null?null:Number(r[key])*(soc?100:key==='storage_charge_kw'?-1:1))}));
 if(soc){for(const [name,key,fallback] of [['SOC下限','soc_min_ratio',.1],['SOC上限','soc_max_ratio',.95]] as const)series.push({name,type:'line',symbol:'none',lineStyle:{type:'dashed'},data:rows.map(()=>100*(result.value.parameters[key]??fallback))})}
 if(voltage){for(const [name,key] of [['电压下限','voltage_min_pu'],['电压上限','voltage_max_pu'],['线性保护阈值','linear_voltage_guard_pu']] as const)series.push({name,type:'line',symbol:'none',lineStyle:{type:'dashed'},data:rows.map(()=>result.value.network_parameters?.[key]??networkDefaults[key])})}
 plot.setOption({tooltip:{trigger:'axis'},legend:{type:'scroll',data:series.map(s=>s.name)},grid:{left:65,right:25,bottom:75,top:50},dataZoom:[{type:'inside'},{type:'slider',bottom:10,height:20}],xAxis:{type:'category',data:rows.map((r:any)=>r.timestamp.slice(5,16).replace('T',' '))},yAxis:{type:'value',name:voltage?'电压 / pu':soc?'SOC / %':'kW',...(soc?{min:0,max:100}:voltage?{scale:true}:{})},series});
}

let archiveRead=0;
async function load(id:string){const request=++archiveRead;const projectId=project.value?.id;error.value='';try{const loaded=await api('/api/runs/'+id);if(request!==archiveRead||project.value?.id!==projectId)return;if(loaded.project_id&&loaded.project_id!==projectId)throw Error('该档案不属于当前工程');result.value=loaded;stageSnapshot.value=JSON.stringify(loaded.stages||[]);active.value='电力电量平衡';subsection.value='平衡结果';balanceMode.value='汇总／网络平衡';projectMessage.value='已读取档案 '+id.slice(0,8)+'，当前工程输入未被覆盖';await draw()}catch(e){if(request===archiveRead&&project.value?.id===projectId)error.value=String(e)}}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){csv.value=await file.text();result.value=null}}
watch([active,chartMode,subsection,balanceMode],draw);onMounted(async()=>{try{projects.value=await api('/api/projects');if(projects.value.length)await openProject(projects.value.find(p=>p.id===localStorage.getItem('terminal-power.last-project'))?.id||projects.value[0].id,false);else await createProject();window.addEventListener('resize',()=>plot?.resize())}catch(e){error.value=String(e)}finally{busy.value=false}});
</script>
<template><div class="shell" :class="{compact:sidebarCompact,presentation,'investment-page':active==='源储协同配置'}"><aside><div class="brand">▦ 末端保供<span>局域电力系统辅助决策</span></div><nav aria-label="业务菜单"><div v-for="(group,i) in workflowNavigation" :key="group.label"><button :class="{selected:currentGroup?.label===group.label}" @click="['专项研究','系统管理'].includes(group.label)?expandedGroup=(expandedGroup===group.label?'':group.label):openWorkflow(group)"><small>{{i===0?'首页':i<6?String(i).padStart(2,'0'):'＋'}}</small>{{group.label}}</button><div v-if="expandedGroup===group.label&&group.label!=='工程工作台'" class="submenus"><button v-for="item in group.items" :key="item.label" :class="{'sub-selected':currentNavigation?.label===item.label&&currentGroup?.label===group.label}" @click="openWorkflow(group,item)">{{item.label}}</button></div></div></nav><footer>本地离线工作空间<br>研发预览版 · 0.1.0</footer></aside><main><header class="top-toolbar"><button class="compact-toggle" @click="sidebarCompact=!sidebarCompact" aria-label="切换侧栏宽度">☰</button><strong>末端保供型局域电力系统软件平台</strong><span class="title-project">当前工程：{{project?.name||'未选择'}}</span><div class="actions"><select :value="project?.id" @change="openProject(($event.target as HTMLSelectElement).value)" :disabled="busy"><option v-for="p in projects" :value="p.id">{{p.name}} · v{{p.revision}}</option></select><button @click="createProject" :disabled="busy">新建工程</button><button @click="saveProject().catch(e=>error=String(e))" :disabled="busy||!project">保存工程</button><a class="backup-link" href="/api/backup" title="下载全部已保存工程、场景与计算档案，不含未保存修改">备份已保存数据</a></div><button @click="navigateSection('系统与接口','计算任务')">任务中心</button></header><section><div class="desktop-menu"><button v-for="name in ['工程','编辑','运行','视图','导出']" :key="name" :class="{current:desktopMenu===name}" @click="desktopMenu=desktopMenu===name?'':name">{{name}}</button><div v-if="desktopMenu" class="desktop-menu-popup"><template v-if="desktopMenu==='工程'"><button @click="createProject();desktopMenu=''" :disabled="busy">新建工程</button><button @click="saveProject().catch(e=>error=String(e));desktopMenu=''" :disabled="busy">保存当前工程</button><a href="/api/backup">备份已保存数据</a></template><template v-if="desktopMenu==='编辑'"><button @click="navigateSection('数据管理','源荷时序');desktopMenu=''">源荷数据编辑</button><button @click="workspacePanel='参数';desktopMenu=''">计算参数</button></template><template v-if="desktopMenu==='运行'"><button @click="navigateSection('电力电量平衡','计算任务');desktopMenu=''">计算任务</button><button @click="navigateSection('系统与接口','计算任务');desktopMenu=''">后台任务中心</button></template><template v-if="desktopMenu==='视图'"><button @click="sidebarCompact=!sidebarCompact;desktopMenu=''">切换工程导航宽度</button><button @click="presentation=!presentation;desktopMenu=''">切换图形展示</button><button @click="workspacePanel='';sidebarCompact=false;presentation=false;desktopMenu=''">恢复默认布局</button></template><template v-if="desktopMenu==='导出'"><a v-if="result" :href="'/api/runs/'+result.id+'/csv'">当前平衡结果 CSV</a><a v-if="result" :href="'/api/runs/'+result.id+'/report'">当前平衡报告 HTML</a><p v-if="!result">请先加载平衡档案。</p></template></div></div><div class="workspace-tools"><span>{{currentNavigation?.label||'图形工作区'}}</span><button v-for="tool in contextTools" :key="tool" @click="runContextTool(tool)" :disabled="busy&&['提交计算','生成场景','生成当前视图','优化运行','复算'].includes(tool)">{{tool}}</button><button @click="presentation=!presentation;nextTick(()=>plot?.resize())">{{presentation?'退出展示':'图形展示'}}</button><button @click="workspacePanel='';presentation=false;sidebarCompact=false;nextTick(()=>plot?.resize())">恢复布局</button></div><div class="workspace-caption">{{currentGroup?.label}} / {{currentNavigation?.label}}<span>{{busy?'处理中':'本地工作区'}}</span></div><div class="heading"><div><small>末端保供 / 工程分析工作空间</small><h1>{{currentNavigation?.label||active}}</h1></div><span class="tag">课题2分析已接入</span></div><details class="development-boundary"><summary>研发范围与验证边界</summary><p class="notice">研发边界：当前接入课题2真实平衡算法及八项策略触发。可选择IEEE33节点网络平衡与交流潮流复核；已支持故障状态抽样与连续修复场景；合成数据仅供联调，尚不含经校准的多样本概率评估与动态稳定校核。</p></details><p v-if="error" class="error">{{error}}</p><article class="workflow-context"><p>{{project?.name||'未选择工程'}} / {{currentGroup?.label}} / {{currentNavigation?.label}}</p><p>源荷 {{inspectTimeSeries(csv).count}} 小时 · {{inspectTimeSeries(csv).totalIssues?'输入需检查':'时序格式已就绪'}} · 工程版本 {{project?.revision||'—'}} · {{busy?'正在处理':result?'已有平衡档案，输入变动后需复算':'尚未加载平衡结果'}}</p><div v-if="currentNavigation&&!['电力电量平衡','源储协同配置'].includes(active)&&currentNavigation.sections.length>1" class="module-tabs"><button v-for="item in currentNavigation.sections" :key="item" :class="{current:subsection===item}" @click="navigateSection(active,item)">{{item}}</button></div></article>
<template v-if="active==='工程工作台'&&project"><ProjectOverview :csv="csv" :history="history" :scenario-id="scenarioId" :production-id="activeProductionId" :model="model" :stages="stages.length" @navigate="active=$event" @open="load"/><details><summary>工程信息详情</summary><article id="project-info"><h3>工程信息</h3><label class="field">工程名称<input v-model="project.name" :disabled="busy"></label><label class="field">所在区域<input v-model="project.region" :disabled="busy"></label><label class="field">工程类型<select v-model="project.kind" :disabled="busy"><option>县域级</option><option>乡镇级</option><option>村级</option><option>村镇级</option></select></label><p>工程数据、资源参数、阶段和场景引用随工程保存。切换前自动保存当前工程。</p></article></details></template><div v-else-if="active==='数据管理'" class="data-page" :class="{'network-page':subsection==='电网拓扑'}"><article v-if="subsection==='数据版本管理'"><h3>数据校验与版本核对</h3><p>源荷：{{inspectTimeSeries(csv).count}}小时，{{inspectTimeSeries(csv).totalIssues}}项格式问题。网络：{{customNetwork?'已应用自定义网络':'未应用自定义网络，将使用IEEE33示例'}}。工程版本：{{project?.revision||'—'}}。</p><p>下方查看已保存的数据版本；逐设备计算还需在对应模式核对台账版本、设备曲线与模型限制，格式通过不代表全部模型可计算。</p><button @click="navigateSection('保供场景生成','典型场景库')">继续到场景设置</button></article><EngineeringWorkspace v-if="inventorySections.includes(subsection)" :project-id="project?.id||''" :section="subsection"/><DataGovernance v-else-if="['地理与灾害','数据版本管理'].includes(subsection)" :project-id="project?.id||''" :section="subsection"/><DataWorkspace ref="dataWorkspace" v-else v-model="csv" v-model:network="customNetwork" @update:network="model='case33'" v-model:failures="faultSelection" @source="(value,source)=>{applyProjected(value);sourceImport=source;sourceImportCsv=value;stages=[];project.region='阿拉山口';projectMessage='阿拉山口典型负荷已应用，请保存工程'}" :section="subsection" :placement="networkParameters" :parameters="params" :disabled="busy"/><NetworkSummary v-if="subsection==='电网拓扑'" :network="customNetwork"/></div><template v-else-if="active==='保供场景生成'"><details class="scenario-guide"><summary>工况选择与操作说明</summary><article><h3>场景配置与计算流程</h3><label>运行工况 <select v-model="operatingCondition"><option>常规运行</option><option>极端保供</option></select></label><p>{{operatingCondition==='常规运行'?'常规工况可直接配置背景序列，不强制设置极端窗口或故障。':'极端工况按需配置事件窗口、故障与恢复。'}}此选项用于引导配置，不修改已有场景或历史档案。</p><p>① 查看来源：典型场景库为预设模板，源荷时序来自当前工程；模板不代表地区实测结果。② 设置参数：选择增长水平、事件窗口或故障修复参数。③ 点击当前模块的生成按钮后调用后端计算，并保存该模块结果。④ 在生成结果中点击应用或嵌入，再进入电力电量平衡运行计算。⑤ 平衡结果在本页对应结果区及方案与报告中查看；修改参数后须重新生成和计算。</p></article></details><EngineeringWorkspace v-if="['典型场景库','分类目标与优先级'].includes(subsection)" :project-id="project?.id||''" :section="subsection"/><div v-show="subsection==='源荷增长与极端窗口'"><SourceAnalysis :project-id="project?.id||''" :csv="csv" @apply="applyProjected" @window="eventCsv=$event;subsection='生产序列嵌入'"/></div><div v-show="subsection==='近中远期全年背景'"><SourceStudy :project-id="project?.id||''" :csv="csv" :parameters="params" @apply="applyProjected"/></div><div v-show="subsection==='故障与恢复场景'&&operatingCondition==='极端保供'"><ScenarioWorkspace v-if="project" :project-id="project.id" :csv="csv" :open-settings="scenarioSettingsOpen" :event-csv="eventCsv" :condition="operatingCondition" @selected="selectedScenario=$event" @apply="applyScenario"/></div><div v-show="subsection==='生产序列嵌入'"><SequenceWorkspace :parameters="params" v-model="eventCsv" :project-id="project?.id||''" :csv="csv" @apply="applyProduction"/></div></template><template v-else-if="active==='电力电量平衡'"><div class="module-tabs"><button v-for="view in ['分析设置','计算任务','分析结果']" :key="view" :class="{current:balanceView===view}" @click="navigateSection('电力电量平衡',view==='分析设置'?'模型与资源':view==='分析结果'?'平衡结果':'计算任务')">{{view}}</button></div><article v-if="balanceView!=='分析设置'"><label class="field">计算模式<select v-model="balanceMode"><option v-for="mode in ['汇总／网络平衡','逐设备时序调度','随机生产模拟','逐设备年度滚动','原生年度流水线']">{{mode}}</option></select></label><p>当前只展示所选模式。各模式沿用各自输入、归档与结果口径；原生年度流水线为高级研究模式。</p></article><div><p v-if="activeProductionId" class="notice">源荷来自生产序列 {{activeProductionId.slice(0,8)}}；计算报告将保留嵌入设置。<button @click="productionId=null" :disabled="busy">解除序列引用</button></p><p v-if="scenarioId" class="notice">已应用故障场景 {{scenarioId.slice(0,8)}} <button @click="scenarioId=null" :disabled="busy">解除场景</button></p><div v-show="balanceView==='分析设置'" class="grid" id="balance-input"><article><h3>01 / 输入时序</h3><p>来源：{{activeProductionId?'已保存生产序列':sourceImportCsv===csv&&sourceImport?'阿拉山口原始资料转换':'当前工作区输入（来源需核实）'}}。{{projectMessage}}</p><SeriesPreview :csv="csv"/><div class="actions"><button @click="navigateSection('数据管理','源荷时序')">编辑源数据</button><button @click="navigateSection('保供场景生成','典型场景库')">前往场景生成</button></div><p>时序修改统一在数据接入完成；当前页面引用工程输入。</p></article><article v-show="workspacePanel==='参数'" class="parameter-dock"><button @click="workspacePanel=''">关闭编辑器</button><h3>模型与资源参数</h3><label class="field">计算模型<select v-model="model" :disabled="busy"><option value="aggregate">汇总逐时平衡</option><option value="case33">{{customNetwork?customNetwork.name:'IEEE33示例'}} · 节点网络平衡</option></select></label><details><summary>资源参数、接入节点与故障设置</summary><template v-if="model==='case33'"><p>采用已应用网络（未配置时使用IEEE33示例），2–168小时。负荷按节点基准比例分配，风光接入节点可设置，其余资源接根节点；仅处理根节点连通区域。</p><label class="field">风电接入节点编号<input type="number" min="1" max="99999" step="1" v-model.number="networkParameters.wind_node" :disabled="busy"></label><label class="field">光伏接入节点编号<input type="number" min="1" max="99999" step="1" v-model.number="networkParameters.pv_node" :disabled="busy"></label><label class="field">电压下限 / pu<input type="number" min="0.8" max="1" step="0.001" v-model.number="networkParameters.voltage_min_pu" :disabled="busy"></label><label class="field">电压上限 / pu<input type="number" min="1" max="1.2" step="0.001" v-model.number="networkParameters.voltage_max_pu" :disabled="busy"></label><label class="field">线性调度电压保护阈值 / pu<input type="number" min="0.8" max="1" step="0.001" v-model.number="networkParameters.linear_voltage_guard_pu" :disabled="busy"></label><p>根节点电压固定为1 pu；保护阈值用于线性调度，其值须不小于电压下限。交流潮流另按上下限复核。</p><div><p>全时域故障点（启用阶段后由阶段设置替代）</p><FaultPicker v-model="faultSelection" :lines="currentLines" :disabled="busy"/></div><label class="field">统一支路容量 / kW<input type="number" v-model.number="branchLimit" :disabled="busy"></label></template><label v-for="(_,key) in params" class="field">{{labels[key]}}<input type="number" v-model.number="params[key]" :disabled="busy" :step="key.includes('ratio')||key.startsWith('eta_')?0.01:100" min="0"></label></details><p>关键、重要负荷按占比分组并按优先级供电，剩余为一般负荷；这不等同逐户负荷数据库。无该类负荷时原算法满足率记为1。</p><button @click="saveProject().then(()=>navigateSection('电力电量平衡','计算任务')).catch(e=>error=String(e))" :disabled="busy">保存设置并进入计算</button><p>计算结果自动归档；修改输入后需重新计算。</p></article></div><div v-show="balanceView==='分析设置'&&workspacePanel==='参数'" id="balance-phases"><PhaseEditor v-model="stages" :disabled="busy" :network="model==='case33'" :lines="currentLines" :hours="inspectTimeSeries(csv).count"/></div><SeriesPreview v-if="balanceView==='计算任务'" :csv="csv"/><article v-if="balanceView==='计算任务'&&balanceMode==='汇总／网络平衡'"><h3>汇总／网络平衡计算</h3><p v-if="inputIssue" class="error">不能提交：{{inputIssue}}</p><p v-else>✓ 当前时序与运行阶段校验通过，提交时服务端继续核验参数。</p><p>使用分析设置中的当前输入；汇总模型支持2–8760小时，网络模型支持2–168小时。运行阶段必须覆盖完整时序。</p><button class="primary" @click="run" :disabled="busy||!!inputIssue">{{busy?'正在计算并保存…':'提交平衡计算'}}</button><button :disabled="!result" @click="navigateSection('电力电量平衡','平衡结果')">查看结果</button></article><details v-show="balanceView!=='分析设置'&&balanceMode==='逐设备时序调度'" id="balance-device" open><summary>逐设备时序调度 · 展开设置与计算</summary><DeviceDispatch :project-id="project?.id||''"/></details><details v-show="balanceView!=='分析设置'&&balanceMode==='随机生产模拟'" id="balance-random" open><summary>随机生产模拟 · 展开设置与计算</summary><RandomBalance :source="result" :project-id="project?.id||''"/></details><details v-show="balanceView!=='分析设置'&&balanceMode==='逐设备年度滚动'" id="balance-annual" open><summary>逐设备年度滚动 · 展开设置与计算</summary><AnnualWorkspace :project-id="project?.id||''"/></details><div v-show="balanceView==='分析结果'&&balanceMode==='汇总／网络平衡'"><p id="balance-result" v-if="!result" class="notice">尚无平衡结果，请先开始平衡分析或从工程工作台加载档案。</p><p id="balance-network" v-if="!result" class="notice">尚无网络结果，请选择IEEE33模型计算后查看。</p><template v-if="result"><ResultOverview :result="result" :condition="operatingCondition"/><p class="notice" v-if="activeProductionId!==(result.production_sequence_id||null) || scenarioId!==(result.scenario_id||null) || JSON.stringify(stages)!==stageSnapshot || csv!==result.input_csv || !sameParameters(params,result.parameters) || (model==='case33'&&!sameParameters(networkParameters,{...networkDefaults,...result.network_parameters})) || model!==(result.model||'aggregate') || failedLines!==(result.failed_lines||[]).join(',') || branchLimit!==(result.branch_limit_kw||5000)">输入已修改，下方为上次计算结果，请重新计算。</p><article v-show="workspacePanel==='指标'"><h3>计算档案 {{result.id}}</h3><p>模式：{{result.model==='case33'?'网络平衡':'汇总平衡'}} · 工程版本 {{result.project_revision??'未记录'}} · 时段 {{result.rows[0]?.timestamp}} — {{result.rows[result.rows.length-1]?.timestamp}}</p><details><summary>查看本次计算设置快照（只读）</summary><pre>{{JSON.stringify(result.parameters,null,2)}}</pre></details></article><div v-show="workspacePanel==='指标'" class="metrics" id="balance-result"><article><span>最大功率缺额</span><strong>{{result.metrics.max_power_deficit_kw.toFixed(2)}} <small>kW</small></strong></article><article><span>累计缺供电量</span><strong>{{result.metrics.expected_energy_deficit_kwh.toFixed(2)}} <small>kWh</small></strong></article><article><span>关键负荷电量满足率</span><strong>{{(100*result.metrics.critical_load_supply_ratio).toFixed(1)}}%</strong></article></div><article v-show="workspacePanel==='明细'"><h3>03 / 供需时序曲线</h3><p>{{result.scope}}</p><p v-if="result.model==='case33'">交流最低电压：{{Math.min(...result.rows.map((r:any)=>r.ac_min_voltage_pu)).toFixed(4)}} pu · 电压越限时段：{{result.rows.filter((r:any)=>!r.ac_voltage_within_bounds).length}}</p><div class="actions chart-tabs"><button v-for="mode in (result.model==='case33'?['供需平衡','资源出力','储能SOC','网络电压']:['供需平衡','资源出力','储能SOC'])" :class="{'chart-selected':chartMode===mode}" @click="chartMode=mode">{{mode}}</button></div><p v-if="chartMode==='资源出力'">充电以负值表示，放电以正值表示；各曲线取自本次计算逐时结果。</p><p v-if="chartMode==='储能SOC'">SOC为每个小时调度后的储能状态；虚线为本次计算使用的上下限。</p><p v-if="chartMode==='网络电压'">电压为各小时与根节点连通区域的交流潮流极值，虚线取自本次计算约束；不代表孤岛动态稳定。历史记录未保存最高电压时该曲线留空。</p><div ref="chart" class="chart" :aria-label="chartMode+'逐时曲线'"></div><a :href="'/api/runs/'+result.id+'/csv'">导出完整逐时结果 CSV ↓</a>　<a :href="'/api/runs/'+result.id+'/report'">导出计算报告 HTML ↓</a></article><div class="module-tabs"><button v-for="tab in ['分阶段指标','逐时明细',...(result.model==='case33'?['网络明细']:[])]" :class="{current:resultDetail===tab}" @click="resultDetail=tab">{{tab}}</button></div><article v-if="workspacePanel==='明细'&&result.phase_metrics&&resultDetail==='分阶段指标'"><h3>分阶段电力电量指标</h3><p>当前为单条输入轨迹，缺供比例是阶段内缺供时段占比，并非校准后的灾害概率。</p><div class="scroll"><table><tr><th>阶段</th><th>缺供时段占比 / %</th><th>最大功率缺额 / MW</th><th>缺供电量 / MWh</th><th>弃电量 / MWh</th></tr><tr v-for="p in result.phase_metrics"><td>{{p.stage}}</td><td>{{p.electricity_shortage_probability_pct.toFixed(2)}}</td><td>{{p.maximum_electricity_shortage_mw.toFixed(3)}}</td><td>{{p.expected_energy_not_served_mwh.toFixed(3)}}</td><td>{{p.expected_curtailed_energy_mwh.toFixed(3)}}</td></tr></table></div></article><article v-if="workspacePanel==='明细'&&resultDetail==='逐时明细'"><h3>逐时明细（前48行）</h3><div class="scroll"><table><tr><th>时间</th><th>负荷 kW</th><th>供电 kW</th><th>缺供 kW</th><th>SOC</th><th v-if="result.model==='case33'">交流电压范围 / pu</th><th v-if="result.model==='case33'">电压校核</th></tr><tr v-for="r in result.rows.slice(0,48)"><td>{{r.timestamp}}</td><td>{{r.load_kw.toFixed(2)}}</td><td>{{r.load_served_kw.toFixed(2)}}</td><td>{{r.power_deficit_kw.toFixed(2)}}</td><td>{{(r.soc*100).toFixed(1)}}%</td><td v-if="result.model==='case33'">{{r.ac_min_voltage_pu.toFixed(4)}} ～ {{r.ac_max_voltage_pu==null?'未记录':r.ac_max_voltage_pu.toFixed(4)}}</td><td v-if="result.model==='case33'">{{r.ac_voltage_within_bounds?'满足':'越限'}}</td></tr></table></div></article><div v-show="workspacePanel==='明细'&&resultDetail==='网络明细'" id="balance-network"><NetworkResult v-if="result.model==='case33'" :result="result"/><p v-else class="notice">网络逐时结果需选择IEEE33网络模型并计算。</p></div></template><button @click="navigateSection('承灾极限分析','分析设置')">进入承灾极限分析</button></div><details v-show="balanceView!=='分析设置'&&balanceMode==='原生年度流水线'" id="balance-native" open><summary>原生年度流水线 · 展开设置与计算</summary><NativePipeline :project-id="project?.id||''" :csv="csv" :parameters="params" :network-parameters="networkParameters" :branch-limit="branchLimit"/></details></div></template>
